import sys
print("Python:", sys.version)
mods = ["lxml", "defusedxml", "PIL", "pandoc", "docx"]
for m in mods:
    try:
        __import__(m)
        print(m, "OK")
    except Exception as e:
        print(m, "MISSING:", e)

import defusedxml.minidom as minidom

dom = minidom.parse("unpacked/word/document.xml")
body = dom.getElementsByTagName("w:body")[0]
print("Total paragraphs:", len(body.getElementsByTagName("w:p")))
for i, p in enumerate(body.getElementsByTagName("w:p")):
    texts = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild:
            texts.append(t.firstChild.data)
    txt = "".join(texts)
    if txt:
        print(f"[{i}] {txt!r}")

